part of harvest_place_app;

// ================================================================
// PHASE 4I — BANK & PAYMENT RECONCILIATION
// External bank evidence is linked to existing finance records.
// ================================================================

class FinanceBankTransaction{
  final String id,number,direction,reference,description,accountLabel,status,notes;final DateTime? date,createdAt;final double amount,matched,remaining;final int matchCount;
  const FinanceBankTransaction({required this.id,required this.number,required this.direction,required this.reference,required this.description,required this.accountLabel,required this.status,required this.notes,this.date,this.createdAt,required this.amount,required this.matched,required this.remaining,required this.matchCount});
  factory FinanceBankTransaction.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;int i(dynamic v)=>v is num?v.toInt():int.tryParse(v?.toString()??'')??0;return FinanceBankTransaction(id:(d['bank_transaction_id']??'').toString(),number:(d['transaction_number']??'').toString(),direction:(d['direction']??'credit').toString(),reference:(d['reference']??'').toString(),description:(d['description']??'').toString(),accountLabel:(d['account_label']??'').toString(),status:(d['status']??'unmatched').toString(),notes:(d['notes']??'').toString(),date:DateTime.tryParse((d['transaction_date']??'').toString()),createdAt:DateTime.tryParse((d['created_at']??'').toString()),amount:n(d['amount']),matched:n(d['matched_amount']),remaining:n(d['remaining_amount']),matchCount:i(d['match_count']));}
}
class BankMatchCandidate{
  final String sourceType,sourceId,label,counterparty,reference,direction;final DateTime? eventDate;final double sourceAmount,sourceMatched,remaining;final int score;
  const BankMatchCandidate({required this.sourceType,required this.sourceId,required this.label,required this.counterparty,required this.reference,required this.direction,this.eventDate,required this.sourceAmount,required this.sourceMatched,required this.remaining,required this.score});
  factory BankMatchCandidate.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;int i(dynamic v)=>v is num?v.toInt():int.tryParse(v?.toString()??'')??0;return BankMatchCandidate(sourceType:(d['source_type']??'').toString(),sourceId:(d['source_id']??'').toString(),label:(d['source_label']??'Finance record').toString(),counterparty:(d['counterparty']??'').toString(),reference:(d['reference']??'').toString(),direction:(d['direction']??'').toString(),eventDate:DateTime.tryParse((d['event_date']??'').toString()),sourceAmount:n(d['source_amount']),sourceMatched:n(d['source_matched_amount']),remaining:n(d['source_remaining_amount']),score:i(d['match_score']));}
}
class BankReconciliationLink{
  final String id,sourceType,sourceId,label,counterparty,status,reversalReason;final double amount;final DateTime? matchedAt,reversedAt;
  const BankReconciliationLink({required this.id,required this.sourceType,required this.sourceId,required this.label,required this.counterparty,required this.status,required this.reversalReason,required this.amount,this.matchedAt,this.reversedAt});
  factory BankReconciliationLink.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return BankReconciliationLink(id:(d['link_id']??'').toString(),sourceType:(d['source_type']??'').toString(),sourceId:(d['source_id']??'').toString(),label:(d['source_label']??'Finance record').toString(),counterparty:(d['counterparty']??'').toString(),status:(d['status']??'active').toString(),reversalReason:(d['reversal_reason']??'').toString(),amount:n(d['matched_amount']),matchedAt:DateTime.tryParse((d['matched_at']??'').toString()),reversedAt:DateTime.tryParse((d['reversed_at']??'').toString()));}
}
Future<List<FinanceBankTransaction>> fetchFinanceBankTransactions({String status='open'})async{await requireAdminAccess();final r=await supabase.rpc('admin_list_bank_transactions',params:{'p_status':status,'p_limit':250});return (r as List).map((e)=>FinanceBankTransaction.fromSupabase(Map<String,dynamic>.from(e as Map))).toList();}
Future<void> createFinanceBankTransaction({required DateTime date,required String direction,required double amount,String reference='',String description='',String accountLabel='',String notes=''})async{await requireAdminAccess();await supabase.rpc('admin_create_bank_transaction',params:{'p_transaction_date':'${date.year.toString().padLeft(4,'0')}-${date.month.toString().padLeft(2,'0')}-${date.day.toString().padLeft(2,'0')}','p_direction':direction,'p_amount':amount,'p_reference':reference.trim(),'p_description':description.trim(),'p_account_label':accountLabel.trim(),'p_external_id':null,'p_notes':notes.trim()});}
Future<List<BankMatchCandidate>> fetchBankMatchCandidates(String bankId)async{await requireAdminAccess();final r=await supabase.rpc('admin_list_bank_match_candidates',params:{'p_bank_transaction_id':bankId,'p_limit':50});return (r as List).map((e)=>BankMatchCandidate.fromSupabase(Map<String,dynamic>.from(e as Map))).toList();}
Future<void> reconcileFinanceBankTransaction({required String bankId,required BankMatchCandidate candidate,required double amount})async{await requireAdminAccess();await supabase.rpc('admin_reconcile_bank_transaction',params:{'p_bank_transaction_id':bankId,'p_source_type':candidate.sourceType,'p_source_id':candidate.sourceId,'p_amount':amount});}
Future<void> ignoreFinanceBankTransaction(String bankId,String reason)async{await requireAdminAccess();await supabase.rpc('admin_ignore_bank_transaction',params:{'p_bank_transaction_id':bankId,'p_reason':reason.trim()});}
Future<List<BankReconciliationLink>> fetchBankReconciliationLinks(String bankId)async{await requireAdminAccess();final r=await supabase.rpc('admin_list_bank_reconciliation_links',params:{'p_bank_transaction_id':bankId});return (r as List).map((e)=>BankReconciliationLink.fromSupabase(Map<String,dynamic>.from(e as Map))).toList();}
Future<void> reverseBankReconciliationLink(String linkId,String reason)async{await requireAdminAccess();await supabase.rpc('admin_reverse_bank_reconciliation_link',params:{'p_link_id':linkId,'p_reason':reason.trim()});}

class BankReconciliationScreen extends StatefulWidget{const BankReconciliationScreen({super.key});@override State<BankReconciliationScreen> createState()=>_BankReconciliationScreenState();}
