  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:FarmColors.background,appBar:AppBar(title:const Text('Bank Reconciliation'),actions:[IconButton(onPressed:_add,icon:const Icon(Icons.add_rounded))]),floatingActionButton:FloatingActionButton(onPressed:_add,child:const Icon(Icons.add_rounded)),body:FutureBuilder<List<FinanceBankTransaction>>(future:_future,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting&&snapshot.data==null)return const Center(child:CircularProgressIndicator());if(snapshot.hasError&&snapshot.data==null)return Center(child:Text(friendlyAppError(snapshot.error!)));final rows=snapshot.data??<FinanceBankTransaction>[];return RefreshIndicator(onRefresh:_refresh,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.fromLTRB(16,16,16,110),children:[const FarmCard(padding:EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Bank & Payment Reconciliation',style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),SizedBox(height:4),Text('Record statement transactions and match them to existing customer payments, farmer settlements, customer refunds or supplier recoveries. Original finance records are not rewritten.',style:TextStyle(color:FarmColors.mutedText,fontSize:10.5,height:1.35,fontWeight:FontWeight.w600))])),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:{'open':'Open','unmatched':'Unmatched','partial':'Partial','matched':'Matched','ignored':'Ignored','all':'All'}.entries.map((e)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(e.value),selected:_status==e.key,onSelected:(_){setState((){_status=e.key;_future=fetchFinanceBankTransactions(status:_status);});}))).toList())),const SizedBox(height:12),if(rows.isEmpty)const FarmEmptyState(icon:Icons.account_balance_outlined,title:'No bank transactions in this view',message:'Use + to add a bank transaction for 